local item_lib = require("items")
local rewarded = false
function event_signal(e)
  if e.signal == 1 then e.self:Say("We thought it was too late, the Dain will be very pleased!")
  elseif e.signal == 2 then e.self:Say("Please friend, show me your Mithril ring and I will show you our gratitude.") end
end
function event_trade(e)
  if not rewarded and item_lib.check_turn_in(e.trade, {item1 = 30162}) then
    rewarded = true
    e.self:Say("Thank you, " .. e.other:GetCleanName() .. ". Your deeds will be mentioned to the Dain. Please take this note from Corbin to Garadain. It may help him to achieve victory over the enemy.")
    e.other:Faction(406, 15); e.other:Faction(405, 3)
    e.other:Faction(448, -1); e.other:Faction(419, -7)
    e.other:SummonItem(1047); e.other:AddEXP(5000)
    -- Waiting Dobbin already has an authored respawn; do not duplicate him.
    eq.depop()
  end
  item_lib.return_items(e.self, e.other, e.trade)
end
